-- Stage 4 authorization/concealment/idempotency/recovery assertions against the
-- authorized development Cloud database, without Docker or extra extensions.
-- Run as ONE transaction. All random fixtures, temporary key configuration and
-- administrator-only clock changes roll back. Never substitute real room IDs.
begin;
set local plpgsql.check_asserts = on;
do $$
declare
  v_a uuid := gen_random_uuid(); v_b uuid := gen_random_uuid(); v_outsider uuid := gen_random_uuid();
  v_c uuid := gen_random_uuid(); v_d uuid := gen_random_uuid();
  v_key text := gen_random_uuid()::text || gen_random_uuid()::text;
  v_request uuid := gen_random_uuid(); v_second uuid := gen_random_uuid();
  v_room uuid; v_code text; v_snapshot jsonb; v_peer jsonb; v_job jsonb; v_result jsonb;
  v_id uuid; v_deadline timestamptz; v_saved_at timestamptz; v_denied boolean;
  v_lines jsonb := '{"themeId":"jungle","introduction":"Welcome {playerA} and {playerB}. Our topic is {topic}.","opening":"{speaker}, your opening remains private until both finish.","rebuttal":"{speaker}, consider the opposing reasoning.","questions":"{speaker}, please answer the saved clarification question.","complete":"The record is complete. No winner is selected."}'::jsonb;
begin
  assert not has_table_privilege('authenticated','quarrel_private.judge_messages','SELECT'), 'Clients cannot directly read judge rows';
  assert not has_table_privilege('authenticated','quarrel_private.judge_messages','INSERT'), 'Clients cannot forge judge messages';
  assert not has_table_privilege('authenticated','quarrel_private.judge_settings','SELECT'), 'Worker hash cannot be read';
  assert not has_table_privilege('authenticated','quarrel_private.judge_settings','UPDATE'), 'Worker key cannot be replaced';
  assert (select bool_and(relrowsecurity) from pg_class where oid in ('quarrel_private.judge_messages'::regclass,'quarrel_private.judge_settings'::regclass)), 'New private tables require RLS';
  assert not exists(select 1 from pg_publication_tables where schemaname='quarrel_private' and tablename in ('judge_messages','judge_settings')), 'No private judge content in Realtime';
  assert not has_function_privilege('authenticated','quarrel_private.assert_judge_server(text)','EXECUTE'), 'Server key helper is private';
  assert not has_function_privilege('authenticated','quarrel_private.reconcile_judge(uuid)','EXECUTE'), 'Clients cannot target another room for recovery';
  assert not has_function_privilege('anon','public.claim_quarrel_judge_work(text)','EXECUTE'), 'Worker requires authenticated role';
  assert not has_function_privilege('anon','public.finish_quarrel_judge_work(uuid,jsonb,text)','EXECUTE'), 'Anonymous role cannot publish judge text';
  update quarrel_private.judge_settings set key_hash=sha256(convert_to(v_key,'UTF8')) where singleton;
  insert into auth.users(id,aud,role,is_anonymous,created_at,updated_at) values
    (v_a,'authenticated','authenticated',true,now(),now()),(v_b,'authenticated','authenticated',true,now(),now()),
    (v_outsider,'authenticated','authenticated',true,now(),now()),(v_c,'authenticated','authenticated',true,now(),now()),(v_d,'authenticated','authenticated',true,now(),now());
  execute 'set local role authenticated';
  perform set_config('request.jwt.claim.sub',v_a::text,true);
  v_snapshot:=public.create_quarrel_room('SQL host');perform public.set_quarrel_theme('jungle'); v_room:=(v_snapshot->>'id')::uuid; v_code:=v_snapshot->>'code';
  assert v_snapshot->'judge'='null'::jsonb, 'Unstarted historical room keeps judge disabled';
  perform public.propose_quarrel_debate('Who should wash the dishes?', 'I cooked dinner', 'I washed all week',0);
  perform public.set_quarrel_ready(true);
  perform set_config('request.jwt.claim.sub',v_b::text,true);
  perform public.join_quarrel_room(v_code,'SQL guest'); perform public.approve_quarrel_debate(1); perform public.set_quarrel_ready(true);
  v_denied:=false; begin perform public.start_quarrel_judged_debate(1,v_key,'ai',2,v_lines); exception when sqlstate 'P0001' then assert sqlerrm='HOST_ONLY';v_denied:=true;end;assert v_denied,'Guest cannot start judged debate';
  perform set_config('request.jwt.claim.sub',v_a::text,true);
  v_denied:=false; begin perform public.start_quarrel_judged_debate(1,'not-the-worker-key','ai',2,v_lines); exception when sqlstate 'P0001' then assert sqlerrm='JUDGE_SERVER_UNAUTHORIZED';v_denied:=true;end;assert v_denied,'Member token alone is not worker authority';
  v_denied:=false; begin perform public.start_quarrel_judged_debate(1,v_key,'ai',6,v_lines); exception when sqlstate 'P0001' then assert sqlerrm='INVALID_JUDGE_CONFIG';v_denied:=true;end;assert v_denied,'Quota configuration is bounded';
  v_denied:=false; begin perform public.start_quarrel_judged_debate(1,v_key,'ai',2,jsonb_set(v_lines,'{themeId}','"detective"')); exception when sqlstate 'P0001' then assert sqlerrm='THEME_CHANGED';v_denied:=true;end;assert v_denied,'Theme change race rejects mismatched lines';
  v_snapshot:=public.start_quarrel_judged_debate(1,v_key,'ai',2,v_lines);
  assert v_snapshot #>> '{judge,enabled}'='true','Judge enabled';
  assert v_snapshot #>> '{judge,mode}'='ai','Mode persists';
  assert v_snapshot #>> '{judge,maxMessagesPerTurn}'='2','Initial quota is two';
  assert v_snapshot #>> '{debate,phase}'='opening','Start preserves opening phase';
  assert v_snapshot #>> '{debate,activeSlot}'='A','Start preserves host first';
  assert v_snapshot #> '{debate,questions}'='[]'::jsonb,'Placeholder questions removed for judged debate';
  assert v_snapshot #>> '{judge,messages,0,kind}'='introduction','Introduction stored';
  assert v_snapshot #>> '{judge,messages,0,text}'='Welcome SQL host and SQL guest. Our topic is Who should wash the dishes?.','Introduction uses topic and names';
  assert position(v_key in v_snapshot::text)=0,'Worker key absent from snapshot';
  v_deadline:=(v_snapshot #>> '{debate,turnDeadline}')::timestamptz;
  v_denied:=false;begin perform public.begin_quarrel_judge_message('',1,0,v_request,v_key);exception when sqlstate 'P0001' then assert sqlerrm='INVALID_JUDGE_MESSAGE';v_denied:=true;end;assert v_denied,'Empty messages rejected';
  v_denied:=false;begin perform public.begin_quarrel_judge_message(repeat('x',601),1,0,v_request,v_key);exception when sqlstate 'P0001' then assert sqlerrm='INVALID_JUDGE_MESSAGE';v_denied:=true;end;assert v_denied,'Overlong messages rejected';
  v_denied:=false;begin perform public.begin_quarrel_judge_message('Help',0,0,v_request,v_key);exception when sqlstate 'P0001' then assert sqlerrm='STALE_REVISION';v_denied:=true;end;assert v_denied,'Stale proposal rejected';
  v_denied:=false;begin perform public.begin_quarrel_judge_message('Help',1,2,v_request,v_key);exception when sqlstate 'P0001' then assert sqlerrm='STALE_TURN';v_denied:=true;end;assert v_denied,'Future turn rejected';
  perform set_config('request.jwt.claim.sub',v_b::text,true);
  v_denied:=false;begin perform public.begin_quarrel_judge_message('Help',1,0,v_request,v_key);exception when sqlstate 'P0001' then assert sqlerrm='NOT_YOUR_TURN';v_denied:=true;end;assert v_denied,'Inactive player cannot chat';
  perform set_config('request.jwt.claim.sub',v_a::text,true);
  v_snapshot:=public.begin_quarrel_judge_message('Please examine my position.',1,0,v_request,v_key);
  v_id:=(v_snapshot #>> '{judge,pendingRequestId}')::uuid;
  assert v_id<>v_request,'Database generates message ID separately from retry nonce';
  assert v_snapshot #>> '{judge,messagesUsed}'='1','Reservation consumes one quota';
  assert v_snapshot #>> '{judge,needsWork}'='true','Reserved job awaits worker';
  assert v_snapshot #>> '{debate,turnIndex}'='0','Chat does not advance turn';
  assert (v_snapshot #>> '{debate,turnDeadline}')::timestamptz=v_deadline,'Chat does not alter deadline';
  assert jsonb_array_length(v_snapshot #> '{debate,history}')=0,'Chat does not submit official argument';
  perform set_config('request.jwt.claim.sub',v_b::text,true);
  v_peer:=public.get_quarrel_room();assert v_peer #> '{judge,messages}'=v_snapshot #> '{judge,messages}','Both players share pending conversation';
  perform set_config('request.jwt.claim.sub',v_outsider::text,true);
  assert public.get_quarrel_room() is null,'Outsider receives no room judge history';
  v_denied:=false;begin perform public.claim_quarrel_judge_work(v_key);exception when sqlstate 'P0001' then assert sqlerrm='ROOM_NOT_FOUND';v_denied:=true;end;assert v_denied,'Worker secret does not bypass membership';
  perform set_config('request.jwt.claim.sub',v_a::text,true);
  v_peer:=public.begin_quarrel_judge_message('Please examine my position.',1,0,v_request,v_key);
  assert v_peer #>> '{judge,pendingRequestId}'=v_id::text,'Retry returns same server message ID';
  assert v_peer #>> '{judge,messagesUsed}'='1','Retry does not consume another quota';
  v_denied:=false;begin perform public.begin_quarrel_judge_message('Changed request',1,0,v_request,v_key);exception when sqlstate 'P0001' then assert sqlerrm='JUDGE_REQUEST_CONFLICT';v_denied:=true;end;assert v_denied,'Nonce cannot authorize different input';
  v_denied:=false;begin perform public.finish_quarrel_judge_work(v_id,'{"text":"forged","reaction":"speaking","source":"ai"}',v_key);exception when sqlstate 'P0001' then assert sqlerrm='JUDGE_REQUEST_NOT_CLAIMED';v_denied:=true;end;assert v_denied,'Unclaimed work cannot finish';
  v_job:=public.claim_quarrel_judge_work(v_key);
  assert v_job->>'id'=v_id::text,'Worker gets reserved job';
  assert v_job->>'mode'='ai','Worker gets persisted mode';
  assert v_job #> '{context,arguments}'='[]'::jsonb,'Opening context contains no private arguments';
  assert public.claim_quarrel_judge_work(v_key) is null,'Duplicate worker cannot issue a second model call';
  v_denied:=false;begin perform public.begin_quarrel_judge_message('Another message',1,0,v_second,v_key);exception when sqlstate 'P0001' then assert sqlerrm='JUDGE_BUSY';v_denied:=true;end;assert v_denied,'One pending request at a time';
  v_denied:=false;begin perform public.finish_quarrel_judge_work(v_id,'{"text":"Hi","reaction":"speaking","source":"ai","winner":"A"}',v_key);exception when sqlstate 'P0001' then assert sqlerrm='INVALID_JUDGE_RESPONSE';v_denied:=true;end;assert v_denied,'Judge output cannot write winner or other fields';
  v_result:='{"text":"What agreement did you have about dividing cooking and washing?","reaction":"questioning","source":"ai"}'::jsonb;
  v_snapshot:=public.finish_quarrel_judge_work(v_id,v_result,v_key);
  assert v_snapshot #>> '{judge,pendingRequestId}' is null,'Completion clears thinking';
  assert v_snapshot #>> '{judge,messages,1,text}'=v_result->>'text','Validated response saved';
  assert v_snapshot #>> '{debate,turnIndex}'='0','Judge response cannot advance turn';
  assert (v_snapshot #>> '{debate,turnDeadline}')::timestamptz=v_deadline,'Judge response cannot reset clock';
  v_peer:=public.finish_quarrel_judge_work(v_id,jsonb_set(v_result,'{text}','"Different response"'),v_key);
  assert v_peer #>> '{judge,messages,1,text}'=v_result->>'text','Duplicate completion cannot overwrite response';
  v_denied:=false;begin perform public.begin_quarrel_judge_message('Another message',1,0,v_second,v_key);exception when sqlstate 'P0001' then assert sqlerrm='JUDGE_RATE_LIMITED';v_denied:=true;end;assert v_denied,'Short-term rate limit enforced';
  execute 'reset role';update quarrel_private.judge_messages set created_at=clock_timestamp()-interval '4 seconds' where id=v_id;execute 'set local role authenticated';
  v_snapshot:=public.begin_quarrel_judge_message('What is the other perspective?',1,0,v_second,v_key);v_job:=public.claim_quarrel_judge_work(v_key);
  v_snapshot:=public.finish_quarrel_judge_work((v_job->>'id')::uuid,v_result,v_key);
  assert v_snapshot #>> '{judge,messagesUsed}'='2','Second message allowed';
  v_denied:=false;begin perform public.begin_quarrel_judge_message('Third message',1,0,gen_random_uuid(),v_key);exception when sqlstate 'P0001' then assert sqlerrm='JUDGE_LIMIT_REACHED';v_denied:=true;end;assert v_denied,'Third message rejected';
  perform public.submit_quarrel_argument('PRIVATE_OPENING_SENTINEL: I cooked dinner.',1,0);
  perform set_config('request.jwt.claim.sub',v_b::text,true);
  v_snapshot:=public.begin_quarrel_judge_message('What should I explain?',1,1,gen_random_uuid(),v_key);v_job:=public.claim_quarrel_judge_work(v_key);v_id:=(v_job->>'id')::uuid;
  assert position('PRIVATE_OPENING_SENTINEL' in v_job::text)=0,'Other opening cannot leak through shared AI context';
  assert v_job #> '{context,arguments}'='[]'::jsonb,'Both sides openings excluded until reveal';
  execute 'reset role';update quarrel_private.judge_messages set deadline_at=clock_timestamp()-interval '1 second' where id=v_id;execute 'set local role authenticated';
  v_snapshot:=public.get_quarrel_room();
  assert v_snapshot #>> '{judge,pendingRequestId}' is null,'Crashed worker recovers without rerun';
  assert exists(select 1 from jsonb_array_elements(v_snapshot #> '{judge,messages}') m where m->>'id'=v_id::text and m->>'source'='fallback'),'Lease failure labeled fallback';
  assert public.claim_quarrel_judge_work(v_key) is null,'Expired work never reclaims AI';
  perform public.submit_quarrel_argument('I washed the dishes every day this week.',1,1);
  perform set_config('request.jwt.claim.sub',v_a::text,true);perform public.submit_quarrel_argument('Cooking took an hour today.',1,2);
  perform set_config('request.jwt.claim.sub',v_b::text,true);v_snapshot:=public.submit_quarrel_argument('We had agreed to share chores equally.',1,3);
  assert v_snapshot #>> '{judge,preparingQuestions}'='true','Both rebuttals queue clarification';
  assert v_snapshot #>> '{debate,phase}'='questions','Existing question phase retained';
  assert v_snapshot #>> '{debate,activeSlot}' is null,'No active player while preparing';
  assert v_snapshot #>> '{debate,turnDeadline}' is null,'Question clock not consumed by generation';
  assert jsonb_array_length(v_snapshot #> '{debate,history}')=4,'All four official arguments preserved';
  v_denied:=false;begin perform public.begin_quarrel_judge_message('Skip questions',1,4,gen_random_uuid(),v_key);exception when sqlstate 'P0001' then assert sqlerrm='JUDGE_PREPARING_QUESTIONS';v_denied:=true;end;assert v_denied,'Chat cannot bypass preparation';
  perform set_config('request.jwt.claim.sub',v_a::text,true);
  v_denied:=false;begin perform public.submit_quarrel_argument('Premature answer',1,4);exception when sqlstate 'P0001' then assert sqlerrm='JUDGE_PREPARING_QUESTIONS';v_denied:=true;end;assert v_denied,'Official answer waits for persisted questions';
  v_job:=public.claim_quarrel_judge_work(v_key);v_id:=(v_job->>'id')::uuid;
  assert v_job->>'kind'='questions','Question job correctly identified';
  assert jsonb_array_length(v_job #> '{context,arguments}')=4,'Question provider sees both openings and rebuttals';
  assert position('PRIVATE_OPENING_SENTINEL' in v_job::text)>0,'Revealed opening now available for questions';
  assert public.claim_quarrel_judge_work(v_key) is null,'Question generation claimed once';
  v_result:='{"text":"Two points need clarification.","reaction":"questioning","source":"ai","questions":[{"slot":"A","text":"How did you agree to divide cooking and cleaning?","source":"ai"},{"slot":"B","text":"What did sharing chores equally mean in your agreement?","source":"ai"}]}'::jsonb;
  v_denied:=false;begin perform public.finish_quarrel_judge_work(v_id,jsonb_set(v_result,'{questions,1,slot}','"A"'),v_key);exception when sqlstate 'P0001' then assert sqlerrm='INVALID_JUDGE_RESPONSE';v_denied:=true;end;assert v_denied,'Questions must cover both players';
  v_snapshot:=public.finish_quarrel_judge_work(v_id,v_result,v_key);
  assert v_snapshot #>> '{judge,preparingQuestions}'='false','Persisted questions end preparation';
  assert v_snapshot #>> '{debate,activeSlot}'='A','Player A answers first';
  assert jsonb_array_length(v_snapshot #> '{debate,questions}')=2,'Both questions saved together';
  assert v_snapshot #>> '{debate,questions,0,text}'<>v_snapshot #>> '{debate,questions,1,text}','Questions are distinct';
  assert v_snapshot #>> '{debate,questions,0,source}'='ai','AI question origin retained';
  select (m->>'completedAt')::timestamptz into v_saved_at from jsonb_array_elements(v_snapshot #> '{judge,messages}') m where m->>'id'=v_id::text;
  v_deadline:=(v_snapshot #>> '{debate,turnDeadline}')::timestamptz;
  assert v_deadline=v_saved_at+interval '30 seconds','Answer starts with full 30 seconds after persistence';
  v_peer:=public.finish_quarrel_judge_work(v_id,v_result,v_key);
  assert (v_peer #>> '{debate,turnDeadline}')::timestamptz=v_deadline,'Repeated finish cannot extend answer timer';
  perform set_config('request.jwt.claim.sub',v_b::text,true);v_peer:=public.get_quarrel_room();
  assert v_peer #> '{debate,questions}'=v_snapshot #> '{debate,questions}','Both browsers get identical questions';
  assert v_peer #> '{judge,messages}'=v_snapshot #> '{judge,messages}','Both browsers get identical judge history';
  perform set_config('request.jwt.claim.sub',v_a::text,true);perform public.submit_quarrel_argument('We had no explicit arrangement.',1,4);
  perform set_config('request.jwt.claim.sub',v_b::text,true);v_snapshot:=public.submit_quarrel_argument('We meant alternating tasks.',1,5);
  assert v_snapshot #>> '{debate,phase}'='verdict','All six official turns reach placeholder verdict';
  assert not (v_snapshot #> '{debate}' ? 'winner'),'Judge never generates actual winner';
  assert jsonb_array_length(v_snapshot #> '{debate,history}')=6,'All official entries remain separate';
  assert (select count(*) from jsonb_array_elements(v_snapshot #> '{judge,messages}') m where m->>'kind'='questions')=1,'Exactly one question job per debate';
  v_denied:=false;begin perform public.begin_quarrel_judge_message('One more',1,5,gen_random_uuid(),v_key);exception when sqlstate 'P0001' then assert sqlerrm='DEBATE_COMPLETE';v_denied:=true;end;assert v_denied,'Completed debate disallows new judge messages';
  -- Separate random fixture: offline catchup reaches preparation, saves fallback
  -- questions on recovery, and only then grants the full first 30-second window.
  perform set_config('request.jwt.claim.sub',v_c::text,true);v_snapshot:=public.create_quarrel_room('Recovery host');perform public.set_quarrel_theme('jungle');v_room:=(v_snapshot->>'id')::uuid;v_code:=v_snapshot->>'code';
  perform public.propose_quarrel_debate('Campus transport','More buses','More walking',0);perform public.set_quarrel_ready(true);
  perform set_config('request.jwt.claim.sub',v_d::text,true);perform public.join_quarrel_room(v_code,'Recovery guest');perform public.approve_quarrel_debate(1);perform public.set_quarrel_ready(true);
  perform set_config('request.jwt.claim.sub',v_c::text,true);perform public.start_quarrel_judged_debate(1,v_key,'demo',2,v_lines);
  execute 'reset role';update quarrel_private.debates set turn_deadline=clock_timestamp()-interval '5 minutes' where room_id=v_room;execute 'set local role authenticated';
  v_snapshot:=public.get_quarrel_room();
  assert v_snapshot #>> '{debate,phase}'='questions','Offline catchup reaches questions';
  assert v_snapshot #>> '{debate,turnIndex}'='4','Prepared first question is not silently skipped';
  assert v_snapshot #>> '{judge,preparingQuestions}'='false','Queued but unclaimed work also recovers';
  assert v_snapshot #>> '{debate,questions,0,source}'='fallback','Recovered question labeled fallback';
  assert (v_snapshot #>> '{debate,turnDeadline}')::timestamptz > clock_timestamp()+interval '29 seconds','Recovery preserves complete answer opportunity';
  assert public.claim_quarrel_judge_work(v_key) is null,'Recovery never makes a delayed duplicate provider call';
  assert jsonb_array_length(v_snapshot #> '{debate,history}')=4,'Only already-running player clocks caught up';
  execute 'reset role';
end;
$$;
select 'Stage 4 Cloud SQL assertions passed; all generated fixtures and temporary configuration are rolled back.' as result;
rollback;
